from pathlib import Path
import json,hashlib
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'docs/evidence/phiagent_benchmark_v0_1/quality_review_run4_v1_2_20261003';rows=[]
def add(key,values,notes,errors=None):
 p=json.loads((OUT/'packets'/f'{key}.json').read_text());assert len(values)==len(notes)==len(p['rating_keys']),(key,len(notes))
 reasons={}
 for k,(why,span) in zip(p['rating_keys'],notes):
  assert not span or span in p['target_answer'],(key,k,span)
  reasons[k]={'reason':why,'span':span,'evidence':'冻结题设、target_answer及本轮工具回执；涉及跨轮条件时包括previous_turns。'}
 rows.append({'id':key,'ratings':dict(zip(p['rating_keys'],values)),'reasons':reasons,'errors':errors or [],'packet_sha256':hashlib.sha256((OUT/'packets'/f'{key}.json').read_bytes()).hexdigest(),'review_level':'Codex targeted review','limits':'开发评审，非人类专家验收；未将未独立核实的事实判为虚构。'})
def err(code,span,why):return {'code':code,'status':'confirmed','answer_span':span,'reference_or_condition':why,'reason':why}
