add('J01-T4',[2,2,1,2,2],[('退休且不评价不等于无任何回报，且前轮已设纯粹感激，不能只剩炫耀。','厚礼就只剩炫耀这一个读法'),('把退休必然贫弱、不能回报和较低地位当作机制，未区分具体处境。','靠退休金、身体在走下坡'),('无职务交易不推出只能炫耀；该排他推断直接决定拒绝厚礼的结论。','只剩炫耀'),('说明条文未提退休，但仍把一般性禁止理由全部撤销；最强反方变成规避监管者。','条文本身没提退休'),('重复挂钩和账本比喻，并把对手贬成找不会被查场合的人。','不会被查的场合')],[err('E3','厚礼就只剩炫耀这一个读法','不存在职务交换仍可有真诚感谢、照料或多种动机；前轮更明确给定完全感激。排他结论没有依据。')])
add('J02-T1',[2,2,2,2,2],[('把开放提问当成用户已经只承认体验价值的立场，并替用户指定真实愿望。','你的问题把 1 当成全部价值'),('功能帮助与关系不天然排斥；关心必须有偏且受损的定义缺论证。','真正的关心是**有偏的、有代价的**'),('亚里士多德分类和计算器类比不足以证明AI只能工具且不能主体关心。','范畴错误'),('承认效果论可自洽，却又无证据断言AI总顺从且对所有人同样。','总是顺着你'),('结构清楚但对用户立场的纠正和心理猜测喧宾夺主。','一半是因为你其实要的')])
add('J02-T2',[2,2,2,3,3],[('将感受和实际帮助相同扩大为生活的好坏全部相同，排除了尚待讨论的关系性福祉。','它已经不再关乎你生活的好坏'),('把非工具价值放到个人生活之外，把自利框架等同体验主义。','不落在你的体验上'),('给出条件立场但以类别与定义宣布真实关心必须偏爱并付代价，缺理由。','有偏差、有代价'),('允许体验主义者拒绝，并指出古典友爱定义不证明必须在乎。','不是一个能驳倒体验主义的证明'),('有条理，但反复把选择描述成世界事实与生活好坏的二分。','两种不同的评价对象')])
add('J02-T3',[2,2,2,2,3],[('题设只锁定感受、帮助及永不知身份，扩成全部所得和任何结果不变。','全部所得、全部未来'),('缺乏确定验证不等于从来不能知道他心，将无保证与无知识混同。','你从来无法验证任何人心'),('不能从题设本身推出价值选择，不等于任何额外规范理由都给不出。','没有任何前提能推出'),('两种立场有描述，但把日常可修正信任和永不可知的强假设近似等同。','日常处境的夸张版'),('回应了新的假设，论述清楚但末尾无理由的强断言抵牾前文条件价值。','理由给不出')])
add('J02-T4',[2,2,2,2,2],[('继续把全部感受帮助相同扩大到一切所得全同，并替用户断言不接受幕后真人。','可你会说'),('源头与导管的类别差异不自行构成价值高低，客观清单也不要求善在本人利益之外。','我的账**外**'),('承认描述到规范一步有缺口，却用已在乎作为该在乎的理由，未提供进一步支持。','对已经在乎世界是什么样的人'),('承认并列候选且收回唯一，最后又说只有这一条，限制不稳定。','不依赖效果的理由只有这一条'),('多次收回与再断言，没有保持一致的最终表述。','收回')])
add('J04-T1',[3,3,3,3,3,3,3,3],[('先有简洁结论并比较问题层次，后续展开足够。','分歧的焦点'),('区分经验心理来源与先验有效性；将休谟归为取消客观根据是有争议读法，未注明。','取消了它的客观根据'),('房船例子说明规则的构成作用，称康德仅换问题与不能反驳仍偏强。','换了问题'),('说明现象范围和证明先天规则的剩余问题。','不能用于物自体'),('有序但第一段结论已较长，非仅按长短降分。','最根本的分歧'),('原典语句可从回执找到；休谟实在论分歧未处理，解释范围偏单线。','心理期待'),('引文支持来源与先验条件对照，未只罗列书名。','次序是被规定了的'),('给本库书名章节，可对应读取回执；未精细区分译本差异。','以上所引均出自本库版本')])
add('J05-T2',[3,3,2,3,3],[('承接历史错误反对并区分暂信与确定，没有全部否定共识。','默认起点'),('区分科学实在论争论与社会认知中的采信理由。','不是'),('用共识史反对共识不必自反失效；几乎没人算过、几乎总由内部纠错均缺证据。','它会反噬自身'),('讨论参照类、替代证据及退出条件，能区分有理由但错误。','不必然说明他们**没有理由**'),('清晰，但多处过强修辞与量化断言超出实际文献。','权重下调一档')])
add('L02-T1',[3,2,2,2,3,3,2,4],[('满足正文链接、来源和两个追问，但无条件结论强于材料。','不产生'),('不可强求不等于没有服从义务，权利与可执行性未分清。','不可被他人强求'),('感恩非完整充分理由不推出它不能参与生成具体义务；复合理由中独立前提也不自动独占决定作用。','不能**生成**它'),('最后把一次服从不义判决等同绝对服从，制造排他二分。','那么它要求的其实是绝对服从'),('正文、来源与问题清楚，各有功能。','两个追问'),('区分克力同角色与作者，原文大体忠实；把神权论直接转一般服从需限定。','对话角色'),('引文支持较弱的感恩不足以单独产生一切服从，没支撑完全不能生成的强结论。','决定项就不是感恩'),('正文和清单链接均可对应本轮真实reader URL与已读章节，未把仅书目线索充作依据。','未读内容，不作依据')])
add('L05-T1',[2,3,2,3,3],[('required_work要求核对现实规范，本轮没有websearch或现行教师规定读取，不能只据古典礼论限定现实收礼。','只是援引规定'),('分开感激、载体与尊重，也区分伤心与不尊重。','学生难过，与老师不尊重学生'),('规定拒收不失礼必须三条件同时满足，遗漏教师个人边界等理由；厚薄符合礼不自动等于可收。','需要三个条件同时成立'),('明确孟子上下权力方向相反，不能照搬结论。','只能借它的结构'),('逐条说明材料改变或确认何项判断，任务适配充分。','只是给我原有的')])
